 22→# VEX Common Patterns and Examples
 23→
 24→## Deformation Patterns
 25→
 26→### Sine Wave Deformation
 27→```vex
 28→// Point wrangle
 29→float amp = chf("amplitude");      // 0.5
 30→float freq = chf("frequency");     // 2.0
 31→float offset = chf("offset");      // 0.0
 32→
 33→@P.y += sin(@P.x * freq + offset + @Time) * amp;
 34→```
 35→
 36→### Noise Displacement Along Normal
 37→```vex
 38→// Point wrangle -- requires normals
 39→float amp = chf("amplitude");
 40→float freq = chf("frequency");
 41→float n = snoise(@P * freq + @Time * chf("speed"));
 42→@P += @N * n * amp;
 43→```
 44→
 45→### Twist Deformation
 46→```vex
 47→// Point wrangle
 48→float twist_amount = chf("twist") * @P.y;
 49→float c = cos(twist_amount);
 50→float s = sin(twist_amount);
 51→float x = @P.x * c - @P.z * s;
 52→float z = @P.x * s + @P.z * c;
 53→@P.x = x;
 54→@P.z = z;
 55→// Recompute normals after this (use Normal SOP or set @N manually)
 56→```
 57→
 58→### Taper
 59→```vex
 60→// Point wrangle
 61→float taper = chramp("taper_profile", fit(@P.y, chf("ymin"), chf("ymax"), 0, 1));
 62→@P.x *= taper;
 63→@P.z *= taper;
 64→```
 65→
 66→## Color Patterns
 67→
 68→### Color by Height
 69→```vex
 70→// Point wrangle
 71→float t = fit(@P.y, chf("min_height"), chf("max_height"), 0, 1);
 72→@Cd = chramp("color_ramp", t);
 73→```
 74→
 75→### Color by Curvature
 76→```vex
 77→// Point wrangle (requires normals)
 78→int pts[] = neighbours(0, @ptnum);
 79→float curvature = 0;
 80→foreach (int pt; pts) {
 81→    vector n2 = point(0, "N", pt);
 82→    curvature += 1.0 - dot(@N, n2);
 83→}
 84→curvature /= max(len(pts), 1);
 85→@Cd = chramp("curvature_ramp", curvature);
 86→```
 87→
 88→### Random Color Per Piece
 89→```vex
 90→// Point wrangle (requires i@piece or s@name attribute)
 91→int piece = i@piece;  // or use i@class
 92→float hue = rand(piece * 13.37);
 93→float sat = fit(rand(piece * 7.13), 0, 1, 0.5, 1.0);
 94→@Cd = hsvtorgb(set(hue, sat, 1.0));
 95→```
 96→
 97→## Geometry Generation
 98→
 99→### Spiral Points
100→```vex
101→// Detail wrangle
102→int npts = chi("num_points");
103→float radius = chf("radius");
104→float height = chf("height");
105→float turns = chf("turns");
106→
107→for (int i = 0; i < npts; i++) {
108→    float t = float(i) / float(npts - 1);
109→    float angle = t * turns * 2 * PI;
110→    float r = radius * (1.0 - t * chf("taper"));
111→    vector pos = set(cos(angle) * r, t * height, sin(angle) * r);
112→    int pt = addpoint(0, pos);
113→    setpointattrib(0, "pscale", pt, lerp(chf("scale_start"), chf("scale_end"), t), "set");
114→}
115→```
116→
117→### Connect Points as Polyline
118→```vex
119→// Detail wrangle (run after point creation)
120→int npts = npoints(0);
121→if (npts < 2) return;
122→
123→int prim = addprim(0, "polyline");
124→for (int i = 0; i < npts; i++) {
125→    addvertex(0, prim, i);
126→}
127→```
128→
129→### Grid from Scratch
130→```vex
131→// Detail wrangle
132→int rows = chi("rows");
133→int cols = chi("cols");
134→float spacing = chf("spacing");
135→
136→// Create points
137→int pts[];
138→resize(pts, rows * cols);
139→for (int r = 0; r < rows; r++) {
140→    for (int c = 0; c < cols; c++) {
141→        vector pos = set(c * spacing, 0, r * spacing);
142→        pts[r * cols + c] = addpoint(0, pos);
143→    }
144→}
145→
146→// Create quads
147→for (int r = 0; r < rows - 1; r++) {
148→    for (int c = 0; c < cols - 1; c++) {
149→        int p0 = pts[r * cols + c];
150→        int p1 = pts[r * cols + c + 1];
151→        int p2 = pts[(r+1) * cols + c + 1];
152→        int p3 = pts[(r+1) * cols + c];
153→        addprim(0, "poly", p0, p1, p2, p3);
154→    }
155→}
156→```
