158→## Grouping Patterns
159→
160→### Group by Bounding Box
161→```vex
162→// Point wrangle
163→vector bmin = chv("bbox_min");
164→vector bmax = chv("bbox_max");
165→i@group_inside = (@P.x >= bmin.x && @P.x <= bmax.x &&
166→                  @P.y >= bmin.y && @P.y <= bmax.y &&
167→                  @P.z >= bmin.z && @P.z <= bmax.z) ? 1 : 0;
168→```
169→
170→### Group by Normal Direction
171→```vex
172→// Point wrangle
173→vector up = {0, 1, 0};
174→float threshold = chf("angle_threshold");  // cos of angle, e.g. 0.7
175→i@group_upfacing = (dot(@N, up) > threshold) ? 1 : 0;
176→```
177→
178→### Group Every Nth Point
179→```vex
180→// Point wrangle
181→int n = chi("every_nth");
182→i@group_selected = (@ptnum % n == 0) ? 1 : 0;
183→```
184→
185→## Solver / Simulation Patterns
186→
187→### Point Advection (SOP Solver)
188→```vex
189→// Point wrangle inside SOP Solver
190→vector vel = v@v;
191→float dt = @TimeInc;
192→@P += vel * dt;
193→
194→// Add gravity
195→v@v += {0, -9.81, 0} * dt;
196→
197→// Ground collision
198→if (@P.y < 0) {
199→    @P.y = 0;
200→    v@v.y = abs(v@v.y) * chf("bounce");
201→    v@v *= chf("friction");
202→}
203→```
204→
205→### Attribute Decay Over Time
206→```vex
207→// Point wrangle (inside solver or with time dependency)
208→float decay = chf("decay_rate");  // e.g. 0.95
209→f@temperature *= pow(decay, @TimeInc * 30);  // Frame-rate independent
210→```
211→
212→## Transfer / Blend Patterns
213→
214→### Transfer Attribute by Proximity
215→```vex
216→// Point wrangle (source on input 1)
217→float radius = chf("radius");
218→int pts[] = pcfind(1, "P", @P, radius, chi("maxpts"));
219→
220→if (len(pts) > 0) {
221→    float total_w = 0;
222→    vector total_cd = {0,0,0};
223→    foreach (int pt; pts) {
224→        float d = distance(@P, point(1, "P", pt));
225→        float w = 1.0 - smooth(0, radius, d);
226→        total_cd += point(1, "Cd", pt) * w;
227→        total_w += w;
228→    }
229→    if (total_w > 0) {
230→        float blend = chf("blend");
231→        @Cd = lerp(@Cd, total_cd / total_w, blend);
232→    }
233→}
234→```
235→
236→### Smooth / Relax Points
237→```vex
238→// Point wrangle (iterate multiple times via feedback loop)
239→int pts[] = neighbours(0, @ptnum);
240→if (len(pts) == 0) return;
241→
242→vector avg = {0,0,0};
243→foreach (int pt; pts) {
244→    avg += point(0, "P", pt);
245→}
246→avg /= len(pts);
247→
248→float strength = chf("smooth_strength");  // 0.1 - 0.5
249→@P = lerp(@P, avg, strength);
250→```
251→
252→### Edge Detection
253→```vex
254→// Point wrangle
255→int pts[] = neighbours(0, @ptnum);
256→float max_diff = 0;
257→foreach (int pt; pts) {
258→    float diff = abs(@density - point(0, "density", pt));
259→    max_diff = max(max_diff, diff);
260→}
261→f@edge = max_diff;
262→i@group_edges = (max_diff > chf("edge_threshold")) ? 1 : 0;
263→```
